CREATE OR REPLACE FUNCTION app_private.assign_staff_seller(_staff uuid,_seller uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'admin only'; END IF; IF NOT EXISTS(SELECT 1 FROM user_roles WHERE user_id=_staff AND role IN ('employee','manager')) OR NOT EXISTS(SELECT 1 FROM profiles WHERE user_id=_seller) OR EXISTS(SELECT 1 FROM user_roles WHERE user_id=_seller AND role IN ('admin','employee','manager','partner')) THEN RAISE EXCEPTION 'Invalid assignment'; END IF; INSERT INTO manager_seller_assignments(manager_user_id,seller_user_id,assigned_by) VALUES(_staff,_seller,auth.uid()) ON CONFLICT(manager_user_id,seller_user_id) DO NOTHING; INSERT INTO staff_audit_log(staff_user_id,action,entity_type,entity_id,after) VALUES(auth.uid(),'assign_staff_seller','staff',_staff::text,jsonb_build_object('seller',_seller)); END $$;
CREATE OR REPLACE FUNCTION public.assign_staff_seller(_staff uuid,_seller uuid) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public,app_private AS $$ SELECT app_private.assign_staff_seller($1,$2) $$;
REVOKE ALL ON FUNCTION public.assign_staff_seller(uuid,uuid),app_private.assign_staff_seller(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.assign_staff_seller(uuid,uuid),app_private.assign_staff_seller(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION app_private.set_staff_seller_fees(_seller uuid,_percentage numeric,_fixed numeric,_withdrawal numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _uid uuid:=auth.uid(); _before jsonb; _limits public.staff_fee_limits; BEGIN
IF _uid IS NULL OR NOT public.has_staff_permission(_uid,'fees.edit') OR (NOT public.has_role(_uid,'admin') AND NOT EXISTS(SELECT 1 FROM manager_seller_assignments WHERE manager_user_id=_uid AND seller_user_id=_seller)) THEN RAISE EXCEPTION 'Access denied'; END IF;
IF _percentage IS NULL OR _fixed IS NULL OR _withdrawal IS NULL OR _percentage NOT BETWEEN 0 AND 100 OR _fixed NOT BETWEEN 0 AND 1000000 OR _withdrawal NOT BETWEEN 0 AND 1000000 THEN RAISE EXCEPTION 'Invalid fees'; END IF;
IF NOT public.has_role(_uid,'admin') THEN SELECT * INTO _limits FROM staff_fee_limits WHERE user_id=_uid; IF NOT FOUND OR _percentage<_limits.min_transaction_percentage OR _fixed<_limits.min_transaction_fixed OR _withdrawal<_limits.min_withdrawal_fee THEN RAISE EXCEPTION 'Fee below owner minimum'; END IF; END IF;
PERFORM 1 FROM profiles WHERE user_id=_seller FOR UPDATE;
SELECT to_jsonb(f) INTO _before FROM custom_user_fees f WHERE user_id=_seller;
INSERT INTO custom_user_fees(user_id,transaction_percentage,transaction_fixed,withdrawal_fee,admin_user_id) VALUES(_seller,_percentage,_fixed,_withdrawal,_uid) ON CONFLICT(user_id) DO UPDATE SET transaction_percentage=_percentage,transaction_fixed=_fixed,withdrawal_fee=_withdrawal,admin_user_id=_uid;
INSERT INTO staff_audit_log(staff_user_id,action,entity_type,entity_id,before,after) VALUES(_uid,'set_seller_fees','seller',_seller::text,_before,jsonb_build_object('percentage',_percentage,'fixed',_fixed,'withdrawal',_withdrawal)); END $$;
CREATE OR REPLACE FUNCTION public.set_staff_seller_fees(_seller uuid,_percentage numeric,_fixed numeric,_withdrawal numeric) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public,app_private AS $$ SELECT app_private.set_staff_seller_fees($1,$2,$3,$4) $$;
REVOKE ALL ON FUNCTION public.set_staff_seller_fees(uuid,numeric,numeric,numeric),app_private.set_staff_seller_fees(uuid,numeric,numeric,numeric) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_staff_seller_fees(uuid,numeric,numeric,numeric),app_private.set_staff_seller_fees(uuid,numeric,numeric,numeric) TO authenticated;